//! Observes native blinker commands already generated by the vehicle
//! interface for a voice lane change. Port of carrot's
//! `selfdrive/car/voice_indicator.py` (`native_indicator`,
//! `NativeVoiceIndicator`).
use openpilot_can::Frame;
use openpilot_cereal::car_capnp::{car_control, car_params, car_state};
use serde_json::json;

const ROOT: &str = "/dev/shm/carrot-assistant-lane";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Output {
    Ea02,
    Spas2,
}

/// `native_indicator(cp)`.
pub fn native(cp: car_params::Reader<'_>) -> Option<Output> {
    if cp.get_passive() {
        return None;
    }
    let brand = cp
        .get_brand()
        .ok()
        .and_then(|b| b.to_str().ok())
        .unwrap_or_default();
    let flags = cp.get_flags();
    if brand == "volkswagen" && flags & 16384 != 0 {
        return Some(Output::Ea02);
    }
    const REQUIRED: u32 = (1 << 13) | 1 | (1 << 5); // CANFD | CANFD_HDA2 | ENABLE_BLINKERS
    (brand == "hyundai" && flags & REQUIRED == REQUIRED).then_some(Output::Spas2)
}

fn identity(text: &str) -> bool {
    text.len() == 43
        && text
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

pub struct NativeVoiceIndicator {
    output: Output,
    request: String,
    sent: bool,
    dark: bool,
    last_report: f64,
    last_update: f64,
    last_confirmed: bool,
}

impl NativeVoiceIndicator {
    pub fn new(output: Output) -> Self {
        Self {
            output,
            request: String::new(),
            sent: false,
            dark: false,
            last_report: 0.,
            last_update: 0.,
            last_confirmed: false,
        }
    }

    pub fn update(
        &mut self,
        now: f64,
        cc: car_control::Reader<'_>,
        cs: car_state::Reader<'_>,
        frames: &[Frame],
    ) {
        let request = cc
            .get_assistant_lane_signal_id()
            .ok()
            .and_then(|t| t.to_str().ok())
            .unwrap_or_default();
        if request.is_empty() {
            self.request.clear();
            return;
        }
        if request != self.request || !(0. ..0.35).contains(&(now - self.last_update)) {
            self.request = request.to_owned();
            self.sent = false;
            self.dark = false;
            self.last_confirmed = false;
        }
        self.last_update = now;
        let (left, right) = (cc.get_left_blinker(), cc.get_right_blinker());
        let valid = cc.get_lat_active() && cs.get_can_valid() && left != right && identity(request);
        let lamps = (cs.get_left_blinker(), cs.get_right_blinker());
        let (address, length, byte, shift, value) = match self.output {
            Output::Ea02 => (0x1f0, 8, 4, 0, if left { 1 } else { 2 }),
            Output::Spas2 => (0x16a, 32, 16, 5, if left { 3 } else { 4 }),
        };
        // Only a frame already sent while dark can confirm a later lamp edge.
        let confirmed = valid && self.sent && lamps == (left, right);
        if !valid || (if left { lamps.1 } else { lamps.0 }) {
            self.sent = false;
            self.dark = false;
        } else if !lamps.0 && !lamps.1 {
            self.dark = true;
        }
        if valid
            && self.dark
            && frames.iter().any(|f| {
                f.address == address
                    && f.data.len() == length
                    && (f.data[byte] >> shift) & 7 == value
            })
        {
            self.sent = true;
        }
        if (confirmed || self.last_confirmed)
            && (confirmed != self.last_confirmed || now - self.last_report >= 0.1)
        {
            let record = json!({"route": "native", "id": request,
                "direction": if left { "left" } else { "right" }, "confirmed": confirmed, "time": now});
            let path = std::path::Path::new(ROOT).join("signal.json");
            // Missing feedback must not interrupt the car loop or start a maneuver.
            let _ = std::fs::create_dir_all(ROOT).and_then(|()| {
                let temporary = path.with_extension("tmp");
                std::fs::write(&temporary, record.to_string())?;
                std::fs::rename(&temporary, &path)
            });
            self.last_report = now;
        }
        self.last_confirmed = confirmed;
    }
}
